        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The root cause of the bug was the presence of redundant DSC power down code in the `dcn10_init_hw` function, which was also being handled in the `init_pipes()` function of `dcn31_init_hw`. This duplication could lead to inconsistent power management behavior for the DSCs during the initialization process, potentially causing issues with display functionality.

        Commit message:
        drm/amd/display: Remove redundant dsc power gating from
 init_hw

[Why]
DSC Power down code has been moved from dcn31_init_hw into init_pipes()
Need to remove it from dcn10_init_hw() as well to avoid duplicated action
on dcn1.x/2.x

[How]
Remove DSC power down code from dcn10_init_hw()

Fixes: 8fa6f4c5715c ("drm/amd/display: fixed the DSC power off sequence during Driver PnP")

Reviewed-by: Anthony Koo <Anthony.Koo@amd.com>
Reviewed-by: Eric Yang <Eric.Yang2@amd.com>
Acked-by: Alex Hung <alex.hung@amd.com>
Signed-off-by: Roman Li <Roman.Li@amd.com>
Tested-by: Daniel Wheeler <daniel.wheeler@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>  

        Patch:

 void dcn10_init_hw(struct dc *dc)
 {
 	int i;
 	struct abm *abm = dc->res_pool->abm;
 	struct dmcu *dmcu = dc->res_pool->dmcu;
 	struct dce_hwseq *hws = dc->hwseq;
 	struct dc_bios *dcb = dc->ctx->dc_bios;
 	struct resource_pool *res_pool = dc->res_pool;
 	uint32_t backlight = MAX_BACKLIGHT_LEVEL;
 	bool   is_optimized_init_done = false;

 	if (dc->clk_mgr && dc->clk_mgr->funcs->init_clocks)
 		dc->clk_mgr->funcs->init_clocks(dc->clk_mgr);

 	/* Align bw context with hw config when system resume. */
 	if (dc->clk_mgr->clks.dispclk_khz != 0 && dc->clk_mgr->clks.dppclk_khz != 0) {
 		dc->current_state->bw_ctx.bw.dcn.clk.dispclk_khz = dc->clk_mgr->clks.dispclk_khz;
 		dc->current_state->bw_ctx.bw.dcn.clk.dppclk_khz = dc->clk_mgr->clks.dppclk_khz;
 	}

 	// Initialize the dccg
 	if (dc->res_pool->dccg && dc->res_pool->dccg->funcs->dccg_init)
 		dc->res_pool->dccg->funcs->dccg_init(res_pool->dccg);

 	if (IS_FPGA_MAXIMUS_DC(dc->ctx->dce_environment)) {

 		REG_WRITE(REFCLK_CNTL, 0);
 		REG_UPDATE(DCHUBBUB_GLOBAL_TIMER_CNTL, DCHUBBUB_GLOBAL_TIMER_ENABLE, 1);
 		REG_WRITE(DIO_MEM_PWR_CTRL, 0);

 		if (!dc->debug.disable_clock_gate) {
 			/* enable all DCN clock gating */
 			REG_WRITE(DCCG_GATE_DISABLE_CNTL, 0);

 			REG_WRITE(DCCG_GATE_DISABLE_CNTL2, 0);

 			REG_UPDATE(DCFCLK_CNTL, DCFCLK_GATE_DIS, 0);
 		}

 		//Enable ability to power gate / don't force power on permanently
 		if (hws->funcs.enable_power_gating_plane)
 			hws->funcs.enable_power_gating_plane(hws, true);

 		return;
 	}

 	if (!dcb->funcs->is_accelerated_mode(dcb))
 		hws->funcs.disable_vga(dc->hwseq);

 	hws->funcs.bios_golden_init(dc);

 	if (dc->ctx->dc_bios->fw_info_valid) {
 		res_pool->ref_clocks.xtalin_clock_inKhz =
 				dc->ctx->dc_bios->fw_info.pll_info.crystal_frequency;

 		if (!IS_FPGA_MAXIMUS_DC(dc->ctx->dce_environment)) {
 			if (res_pool->dccg && res_pool->hubbub) {

 				(res_pool->dccg->funcs->get_dccg_ref_freq)(res_pool->dccg,
 						dc->ctx->dc_bios->fw_info.pll_info.crystal_frequency,
 						&res_pool->ref_clocks.dccg_ref_clock_inKhz);

 				(res_pool->hubbub->funcs->get_dchub_ref_freq)(res_pool->hubbub,
 						res_pool->ref_clocks.dccg_ref_clock_inKhz,
 						&res_pool->ref_clocks.dchub_ref_clock_inKhz);
 			} else {
 				// Not all ASICs have DCCG sw component
 				res_pool->ref_clocks.dccg_ref_clock_inKhz =
 						res_pool->ref_clocks.xtalin_clock_inKhz;
 				res_pool->ref_clocks.dchub_ref_clock_inKhz =
 						res_pool->ref_clocks.xtalin_clock_inKhz;
 			}
 		}
 	} else
 		ASSERT_CRITICAL(false);

 	for (i = 0; i < dc->link_count; i++) {
 		/* Power up AND update implementation according to the
 		 * required signal (which may be different from the
 		 * default signal on connector).
 		 */
 		struct dc_link *link = dc->links[i];

 		if (!is_optimized_init_done)
 			link->link_enc->funcs->hw_init(link->link_enc);

 		/* Check for enabled DIG to identify enabled display */
 		if (link->link_enc->funcs->is_dig_enabled &&
 			link->link_enc->funcs->is_dig_enabled(link->link_enc))
 			link->link_status.link_active = true;
 	}

-	/* Power gate DSCs */
-	if (!is_optimized_init_done) {
-		for (i = 0; i < res_pool->res_cap->num_dsc; i++)
-			if (hws->funcs.dsc_pg_control != NULL)
-				hws->funcs.dsc_pg_control(hws, res_pool->dscs[i]->inst, false);
-	}
-
 	/* we want to turn off all dp displays before doing detection */
 	dc_link_blank_all_dp_displays(dc);

 	/* If taking control over from VBIOS, we may want to optimize our first
 	 * mode set, so we need to skip powering down pipes until we know which
 	 * pipes we want to use.
 	 * Otherwise, if taking control is not possible, we need to power
 	 * everything down.
 	 */
 	if (dcb->funcs->is_accelerated_mode(dcb) || !dc->config.seamless_boot_edp_requested) {
 		if (!is_optimized_init_done) {
 			hws->funcs.init_pipes(dc, dc->current_state);
 			if (dc->res_pool->hubbub->funcs->allow_self_refresh_control)
 				dc->res_pool->hubbub->funcs->allow_self_refresh_control(dc->res_pool->hubbub,
 						!dc->res_pool->hubbub->ctx->dc->debug.disable_stutter);
 		}
 	}

 	if (!is_optimized_init_done) {

 		for (i = 0; i < res_pool->audio_count; i++) {
 			struct audio *audio = res_pool->audios[i];

 			audio->funcs->hw_init(audio);
 		}

 		for (i = 0; i < dc->link_count; i++) {
 			struct dc_link *link = dc->links[i];

 			if (link->panel_cntl)
 				backlight = link->panel_cntl->funcs->hw_init(link->panel_cntl);
 		}

 		if (abm != NULL)
 			abm->funcs->abm_init(abm, backlight);

 		if (dmcu != NULL && !dmcu->auto_load_dmcu)
 			dmcu->funcs->dmcu_init(dmcu);
 	}

 	if (abm != NULL && dmcu != NULL)
 		abm->dmcu_is_running = dmcu->funcs->is_dmcu_initialized(dmcu);

 	/* power AFMT HDMI memory TODO: may move to dis/en output save power*/
 	if (!is_optimized_init_done)
 		REG_WRITE(DIO_MEM_PWR_CTRL, 0);

 	if (!dc->debug.disable_clock_gate) {
 		/* enable all DCN clock gating */
 		REG_WRITE(DCCG_GATE_DISABLE_CNTL, 0);

 		REG_WRITE(DCCG_GATE_DISABLE_CNTL2, 0);

 		REG_UPDATE(DCFCLK_CNTL, DCFCLK_GATE_DIS, 0);
 	}
 	if (hws->funcs.enable_power_gating_plane)
 		hws->funcs.enable_power_gating_plane(dc->hwseq, true);

 	if (dc->clk_mgr->funcs->notify_wm_ranges)
 		dc->clk_mgr->funcs->notify_wm_ranges(dc->clk_mgr);
 }



